#include <cstdint>
#include "address.h"
#include "modules.h"

struct gen_aggressive_offset_s0 : public champsim::modules::prefetcher {
    static constexpr std::size_t REGION_SIZE = 16;
    static constexpr std::size_t MAX_OFFSET = 4;
    static constexpr int CONFIDENCE_THRESHOLD = 2;

    struct region_entry {
        int confidence = 0;
        champsim::block_number last_access;
    };

    region_entry regions[1024];

    using prefetcher::prefetcher;

    uint32_t prefetcher_cache_operate(champsim::address addr, champsim::address ip,
                                     uint8_t cache_hit, bool useful_prefetch,
                                     access_type type, uint32_t metadata_in) {
        champsim::block_number blk{addr};
        champsim::block_number region_base{blk - (blk % REGION_SIZE)};

        auto& entry = regions[region_base % std::size(regions)];
        if (entry.last_access == region_base) {
            entry.confidence = std::min(entry.confidence + 1, 3);
        } else {
            entry.confidence = 0;
        }
        entry.last_access = region_base;

        if (entry.confidence >= CONFIDENCE_THRESHOLD) {
            for (std::size_t offset = 1; offset <= MAX_OFFSET; ++offset) {
                prefetch_line(champsim::address{blk + offset}, true, metadata_in);
            }
        }

        return metadata_in;
    }

    uint32_t prefetcher_cache_fill(champsim::address addr, long set, long way,
                                  uint8_t prefetch, champsim::address evicted_addr,
                                  uint32_t metadata_in) {
        return metadata_in;
    }
};

